"use server"

import { revalidatePath } from "next/cache"
import { cookies } from "next/headers"

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const current = cookieStore.get("notifications")?.value === "on"
  cookieStore.set("notifications", current ? "off" : "on")

  revalidatePath("/")
}

"use client"

import { useTransition } from "react"
import { toggleNotifications } from "./actions"

export default function ToggleButton({ enabled }: { enabled: boolean }) {
  const [isPending, startTransition] = useTransition()

  return (
    <form
      action={() => {
        startTransition(async () => {
          await toggleNotifications()
        })
      }}
    >
      <button type="submit" disabled={isPending}>
        {isPending ? "Saving..." : enabled ? "Turn off" : "Turn on"}
      </button>
    </form>
  )
}

import { cookies } from "next/headers"
import ToggleButton from "./ToggleButton"

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get("notifications")?.value === "on"

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Email notifications: <strong>{enabled ? "On" : "Off"}</strong>
      </p>
      <ToggleButton enabled={enabled} />
    </main>
  )
}

export const metadata = { title: "Settings" }

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
